package com.example.demo.model; import jakarta.persistence.*; @Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String name; private String email; public User(){} public User(String n,String e){name=n;email=e;} public Long getId(){return id;} public String getName(){return name;} public void setName(String n){name=n;} public String getEmail(){return email;} public void setEmail(String e){email=e;} public String toString(){return "User{id="+id+", name='"+name+"', email='"+email+"'}";} }